arguments.file_text:
@page "/apply"
@using sv_f4d9bb71bb5d4d50a7b7b3afd94b8672.Models
@using sv_f4d9bb71bb5d4d50a7b7b3afd94b8672.Components.Pages.Application
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@personalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="() => AdvanceToStep(1)" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="() => AdvanceToStep(2)"
                             OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep Entries="@references"
                            OnNext="() => AdvanceToStep(3)"
                            OnBack="() => GoToStep(1)" />
            break;
